print(f"Input: {inp1}")
print(f"Output: {outp1}")

# Find minimal edit
def find_minimal_edit(s_in, s_out):
    # Simple approach: find first position where they differ
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Check if we're removing or replacing
            if len(s_in) > len(s_out):
                # Removing characters
                return (s_in[i:i+len(s_in)-len(s_out)+1], s_out[i:], i)
            else:
                # Adding/replacing characters  
                return (s_in[i], s_out[i], i)
    # If we get here, one string is prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[len(s_out):], '', len(s_out))
    else:
        return ('', s_out[len(s_in):], len(s_in))

